with with_last as (select s.*, x.launch_date from suppliers s join lateral (select c.launch_date from products c where c.supplier_id = s.id order by c.cost desc, c.id desc limit 1) x on true) select case when rating >= 3.5 then 'LARGE' else 'SMALL' end as rating_tier, city, approx_percentile(rating, 0.9) as rating_p90, max(rating) filter (where country = 'DE') as de_max_rating, percentile_approx(rating, array(0.25, 0.5, 0.75)) as rating_quartiles, sum(case when city = 'New York' then rating else 0 end) as new_york_rating from with_last group by 1, 2 order by rating_p90 nulls first;
